local BookshelfMaker = {}
local PRODUCTS = {
    simple_pine_bookshelf = { name = "Preprosta borova knjižna polica", woodCost = 4, time = 5, cost = 90, beauty = 20, education = 12, happiness = 1, description = "Preprosta borova knjižna polica za knjige." },
    carved_oak_bookshelf = { name = "Izrezljana hrastova knjižna polica", woodCost = 4, leatherCost = 1, time = 8, cost = 240, beauty = 38, education = 22, happiness = 2, prestige = 2, description = "Izrezljana hrastova knjižna polica za trgovce." },
    silver_trimmed_bookshelf = { name = "Srebrnoobrobljena knjižna polica", woodCost = 4, silverCost = 1, leatherCost = 1, time = 11, cost = 580, beauty = 52, education = 32, happiness = 2, prestige = 6, description = "Srebrnoobrobljena knjižna polica za plemiče." },
    gold_inlaid_bookshelf = { name = "Zlatovložena knjižna polica", woodCost = 4, goldCost = 1, silverCost = 1, leatherCost = 1, time = 15, cost = 1300, beauty = 68, education = 42, happiness = 3, prestige = 14, description = "Zlatovložena knjižna polica za visoke plemiče." },
    jewel_set_bookshelf = { name = "Draguljasta knjižna polica", woodCost = 4, goldCost = 1, silverCost = 1, leatherCost = 1, jewelCost = 1, time = 19, cost = 2900, beauty = 82, education = 55, happiness = 5, prestige = 27, description = "Knjižna polica z draguljem za visoko plemstvo." },
    royal_grand_bookshelf = { name = "Kraljevski veliki knjižna polica", woodCost = 6, goldCost = 2, silverCost = 2, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 26, cost = 6200, beauty = 95, education = 75, happiness = 12, prestige = 58, description = "Velika kraljevska knjižna polica z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    bookshelf_workshop = { name = "Knjižna polica delavnica", cost = { gold = 260, wood = 180, stone = 100 }, upkeep = 6, qualityBonus = 5 },
    library_loft = { name = "Knjižnična podstrešje", cost = { gold = 950, wood = 320, stone = 220, silver = 6 }, upkeep = 22, qualityBonus = 18 },
    master_cabinet_atelier = { name = "Mojstrski mizarski atelje", cost = { gold = 2700, wood = 380, stone = 480, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_library_palace = { name = "Kraljevska knjižnična palača", cost = { gold = 11500, wood = 600, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
BookshelfMaker.woodStock = 22; BookshelfMaker.leatherStock = 10; BookshelfMaker.silverStock = 6; BookshelfMaker.goldStock = 6; BookshelfMaker.jewelStock = 4; BookshelfMaker.pearlStock = 4
BookshelfMaker.productStock = {}; BookshelfMaker.buildings = {}; BookshelfMaker.maker = nil; BookshelfMaker.activeMaking = {}; BookshelfMaker.totalProducts = 0; BookshelfMaker.dayTimer = 0
function BookshelfMaker.init() BookshelfMaker.woodStock=22; BookshelfMaker.leatherStock=10; BookshelfMaker.silverStock=6; BookshelfMaker.goldStock=6; BookshelfMaker.jewelStock=4; BookshelfMaker.pearlStock=4; BookshelfMaker.productStock={}; BookshelfMaker.buildings={}; BookshelfMaker.maker=nil; BookshelfMaker.activeMaking={}; BookshelfMaker.totalProducts=0; BookshelfMaker.dayTimer=0; print("[BookshelfMaker] Royal Bookshelf Maker System initialized (6 products, 4 buildings)") end
function BookshelfMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookshelfMaker.maker={name=n or ("Knjižničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Knjižničar najet: %s (spretnost: %d)",BookshelfMaker.maker.name,s),"success") end; return true end
function BookshelfMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookshelfMaker.build(id) local ok,e=BookshelfMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookshelfMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookshelfMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookshelfMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookshelfMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and BookshelfMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookshelfMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookshelfMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookshelfMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookshelfMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookshelfMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookshelfMaker.buildings==0 then return false,"Potrebna knjižna polica delavnica" end; if not BookshelfMaker.maker then return false,"Potreben knjižničar" end; return true end
function BookshelfMaker.make(pt,qty) qty=qty or 1; local ok,e=BookshelfMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then BookshelfMaker.woodStock=BookshelfMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookshelfMaker.leatherStock=BookshelfMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookshelfMaker.silverStock=BookshelfMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookshelfMaker.goldStock=BookshelfMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookshelfMaker.jewelStock=BookshelfMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookshelfMaker.pearlStock=BookshelfMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookshelfMaker.maker then t=math.max(1,t-math.floor(BookshelfMaker.maker.skill/12)) end; table.insert(BookshelfMaker.activeMaking,{id="bookshelf_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,education=d.education or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookshelfMaker.completeMaking(m) local q=1.0+(BookshelfMaker.getQualityBonus()/100); if BookshelfMaker.maker then q=q+(BookshelfMaker.maker.skill/140) end; q=math.min(2.5,q); BookshelfMaker.productStock[m.productType]=(BookshelfMaker.productStock[m.productType] or 0)+m.quantity; BookshelfMaker.totalProducts=BookshelfMaker.totalProducts+m.quantity; if m.education>0 and _G.state then _G.state.education=(_G.state.education or 0)+m.education end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookshelfMaker.maker then BookshelfMaker.maker.itemsMade=BookshelfMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookshelfMaker.maker.skill=math.min(100,BookshelfMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Knjižna polica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookshelf.completed",{productName=m.productName,beauty=m.beauty,education=m.education,prestige=m.prestige,happiness=m.happiness}) end end
function BookshelfMaker.update(dt) if not _G.state then return end; BookshelfMaker.dayTimer=BookshelfMaker.dayTimer+dt; if BookshelfMaker.dayTimer>=30 then BookshelfMaker.dayTimer=0; for i=#BookshelfMaker.activeMaking,1,-1 do local m=BookshelfMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookshelfMaker.completeMaking(m); table.remove(BookshelfMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookshelfMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookshelfMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookshelfMaker.getStats() return {woodStock=BookshelfMaker.woodStock,leatherStock=BookshelfMaker.leatherStock,silverStock=BookshelfMaker.silverStock,goldStock=BookshelfMaker.goldStock,jewelStock=BookshelfMaker.jewelStock,pearlStock=BookshelfMaker.pearlStock,productStock=BookshelfMaker.productStock,numBuildings=#BookshelfMaker.buildings,hasMaker=BookshelfMaker.maker~=nil,makerName=BookshelfMaker.maker and BookshelfMaker.maker.name or "—",makerSkill=BookshelfMaker.maker and BookshelfMaker.maker.skill or 0,activeMaking=#BookshelfMaker.activeMaking,totalProducts=BookshelfMaker.totalProducts} end
return BookshelfMaker
